  const pati=buildPati2009Scene(o,r),matuhina=buildMatuhina2023Scene(o,r),sommer=buildSommer2020Scene(o,r),ghosh=buildGhosh2012Scene(o,r),lian=buildLian2021Scene(o,r),morrison=buildMorrison2017Scene(o,r),evans=buildEvans2010Scene(o,r),heo=buildHeo2003Scene(o,r),aerosol=buildAerosolScene(o,r),wafer=buildWaferScene(o,r),danek=buildDanekScene(o,r),dabbousi=buildDabbousiScene(o,r),veinot=buildVeinotScene(o,r),yao=buildYaoScene(o,r),stiger=buildStigerScene(o,r),peng=buildPeng1998Scene(o,r),shah=buildShah2001Scene(o,r),gerion=buildGerion2001Scene(o,r),braun=buildBraun2001Scene(o,r),besson=buildBesson2002Scene(o,r),dantas=buildDantas2002Scene(o,r),yi=buildYi2002Scene(o,r),banerjee=buildBanerjee2003Scene(o,r),schwartz=buildSchwartz2003Scene(o,r),sashchiuk=buildSashchiuk2004Scene(o,r),gu=buildGu2004Scene(o,r),nagasaki=buildNagasaki2004Scene(o,r),ribeiro=buildRibeiro2004Scene(o,r),norberg=buildNorberg2004Scene(o,r);
  const visual=el('div',undefined,'protocol-visual'),copy=el('div',undefined,'protocol-copy');visual.append(art(o,r,prefix),el('p',pati?.caption||matuhina?.caption||sommer?.caption||ghosh?.caption||lian?.caption||morrison?.caption||evans?.caption||heo?.caption||nagasaki?.caption||ribeiro?.caption||norberg?.caption||gu?.caption||sashchiuk?.caption||schwartz?.caption||banerjee?.caption||yi?.caption||dantas?.caption||besson?.caption||braun?.caption||gerion?.caption||shah?.caption||peng?.caption||stiger?.caption||yao?.caption||veinot?.caption||dabbousi?.caption||danek?.caption||wafer?.caption||aerosol?.caption||'Operation schematic. Vessel geometry and liquid colors are illustrative; source-reported equipment and conditions are specified alongside.','protocol-visual-note'));
  if(pati||matuhina||sommer||ghosh||lian||morrison||evans||heo||nagasaki||ribeiro||norberg){const expand=el('button','Enlarge operation diagram ↗','molecule-link');expand.type='button';expand.onclick=()=>expandDiagram(visual.querySelector('svg'),o.label);visual.append(expand);}
  copy.append(el('span',`${String(i+1).padStart(2,'0')} / ${r.operations.length} · ${human(o.stage)}${o.optional?' · optional branch':''}`,'mini-label'),el('h3',o.label),el('p',o.description));
  const dl=pati?createPati2009ConditionGrid(o,r):matuhina?createMatuhina2023ConditionGrid(o,r):sommer?createSommer2020ConditionGrid(o,r):ghosh?createGhosh2012ConditionGrid(o,r):lian?createLian2021ConditionGrid(o,r):morrison?createMorrison2017ConditionGrid(o,r):evans?createEvans2010ConditionGrid(o,r):heo?createHeo2003ConditionGrid(o,r):aerosol?createAerosolConditionGrid(o,r):el('dl',undefined,'protocol-condition-grid');const entries=Object.entries(o.parameters);if(!aerosol&&!heo&&!evans&&!morrison&&!lian&&!ghosh&&!sommer&&!matuhina&&!pati)for(const [key,label] of [['temperature','Temperature'],['duration|time','Duration'],['pressure','Pressure']]){const match=entries.find(([k])=>new RegExp(key).test(k.toLowerCase()));const variants=!match&&key==='temperature'&&danek&&['composite','cap-layer'].includes(o.id)?(r.condition_options||[]).map(c=>c.parameters?.substrate_temperature).filter(Boolean):[];const item=el('div');item.append(el('dt',variants.length?'Substrate temperature (reported variants)':match?human(match[0]):label),el('dd',variants.length?[...new Set(variants.map(v=>amount(v)))].join(' / ')+'; see condition sets':dabbousi&&key==='temperature'&&['heat-seeds','dose'].includes(o.id)&&(r.condition_options||[]).some(c=>c.parameters?.input_core_diameter&&c.parameters?.overgrowth_temperature)?'See source-paired temperatures below':amount(match?.[1])));dl.append(item);}if(!heo&&!evans&&!morrison&&!lian&&!ghosh&&!sommer&&!matuhina&&!pati){const env=el('div');env.append(el('dt','Environment'),el('dd',fact(o.environment)));dl.append(env);}copy.append(dl);
  if(aerosol)for(const note of aerosol.notes)copy.append(el('p',note,'record-note'));
