  if(danek||dabbousi||veinot||yao||stiger||peng||shah||gerion||braun||besson||dantas||yi||banerjee||schwartz||sashchiuk||gu||nagasaki||ribeiro||norberg){const extra=el('dl',undefined,'protocol-condition-grid');for(const [k,v]of entries.filter(([k])=>(gerion||braun||besson||dantas||yi||banerjee||schwartz||sashchiuk||gu||nagasaki||ribeiro||norberg)?!['temperature','duration|time','pressure'].some(pattern=>entries.find(([name])=>new RegExp(pattern).test(name.toLowerCase()))?.[0]===k):/flow|rate|voltage|thickness|concentration|pore_size|beam_energy|accelerating_voltage|volume|path|count|photon_energy|power|current|slit|resolution|q_range|reported_distance|frequency|mesh|drops|line_density|sieve_pore|remaining_volume|duration_threshold|potential|electrode_area|camera_length|aperture|scan_width|scan_height|fields_per_sample|wavelength|two_theta|eluent_pH|diameter|depth/.test(k))){const item=el('div');item.append(el('dt',human(k)),el('dd',amount(v)));extra.append(item);}if(extra.children.length)copy.append(extra);}
