  const controls=el('div',undefined,'protocol-controls');const prev=el('button','← Previous'),next=el('button','Next →');prev.type=next.type='button';prev.disabled=i===0;next.disabled=i===r.operations.length-1;prev.onclick=()=>render(selected-1);next.onclick=()=>render(selected+1);controls.append(prev,next);copy.append(controls);display.append(visual,copy);
